import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;

public class Main {

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int b = readByte();
            while (b <= ' ' && b != -1) b = readByte();
            if (b == -1) return -1;
            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return res;
        }
    }

    static int N, Q;
    static int[] head, to, nxt;
    static int edgeCount = 0;

    static void addEdge(int u, int v) {
        to[edgeCount] = v;
        nxt[edgeCount] = head[u];
        head[u] = edgeCount++;
    }

    static int[][] up;
    static int[] depth;
    static int[] tin, tout;
    static int timer = 0;
    static final int LOGN = 18;

    static void dfs(int u, int p, int d) {
        depth[u] = d;
        up[0][u] = p;
        for (int i = 1; i < LOGN; i++) {
            up[i][u] = up[i - 1][up[i - 1][u]];
        }
        tin[u] = ++timer;
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (v != p) {
                dfs(v, u, d + 1);
            }
        }
        tout[u] = timer;
    }

    static int getKthAncestor(int u, int k) {
        for (int i = 0; i < LOGN; i++) {
            if ((k & (1 << i)) != 0) {
                u = up[i][u];
            }
        }
        return u;
    }

    static int[] segTree;

    static void update(int node, int l, int r, int ql, int qr, int val) {
        if (ql <= l && r <= qr) {
            if (segTree[node] == 0 || depth[val] < depth[segTree[node]]) {
                segTree[node] = val;
            }
            return;
        }
        int mid = (l + r) >> 1;
        if (ql <= mid) update(node << 1, l, mid, ql, qr, val);
        if (qr > mid) update((node << 1) | 1, mid + 1, r, ql, qr, val);
    }

    static int query(int node, int l, int r, int pos) {
        int best = segTree[node];
        if (l == r) return best;
        int mid = (l + r) >> 1;
        int childBest;
        if (pos <= mid) {
            childBest = query(node << 1, l, mid, pos);
        } else {
            childBest = query((node << 1) | 1, mid + 1, r, pos);
        }
        if (childBest != 0 && (best == 0 || depth[childBest] < depth[best])) {
            best = childBest;
        }
        return best;
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        N = scanner.nextInt();
        if (N == -1) return;

        head = new int[N + 1];
        Arrays.fill(head, -1);
        to = new int[N];
        nxt = new int[N];

        for (int i = 2; i <= N; i++) {
            int p = scanner.nextInt();
            addEdge(p, i);
        }

        up = new int[LOGN][N + 1];
        depth = new int[N + 1];
        tin = new int[N + 1];
        tout = new int[N + 1];

        dfs(1, 1, 0);

        segTree = new int[4 * N + 1];

        Q = scanner.nextInt();
        PrintWriter out = new PrintWriter(System.out);

        for (int q = 0; q < Q; q++) {
            int type = scanner.nextInt();
            if (type == 1) {
                int v = scanner.nextInt();
                int k = scanner.nextInt();

                int top = query(1, 1, N, tin[v]);
                if (top == 0) {
                    out.println(getKthAncestor(v, k));
                } else {
                    if (k == 1) {
                        out.println(top);
                    } else {
                        out.println(getKthAncestor(top, k - 1));
                    }
                }
            } else {
                int v = scanner.nextInt();
                int top = query(1, 1, N, tin[v]);
                if (top == 0) {
                    if (tin[v] < tout[v]) {
                        update(1, 1, N, tin[v] + 1, tout[v], v);
                    }
                }
            }
        }

        out.flush();
    }
}
